function legacyLineMetrics(o){const lines=batchOrderLines(o),packed=o.packing?.items;if(packed?.length===lines.length)return packed.map(p=>({kg:p.kg,eggs:p.eggs}));const fixedKg=lines.filter(l=>l.unit==='kg').reduce((s,l)=>s+l.quantity,0),fixedEggs=lines.filter(l=>l.unit==='butir').reduce((s,l)=>s+l.quantity,0),weights=lines.map(l=>l.unit==='kg'?l.quantity:fixedEggs?Math.max(0,o.kg-fixedKg)*l.quantity/fixedEggs:0),counts=lines.map(l=>l.unit==='butir'?l.quantity:fixedKg?Math.max(0,o.stockEggs-fixedEggs)*l.quantity/fixedKg:0),w=weights.reduce((s,n)=>s+n,0),e=counts.reduce((s,n)=>s+n,0);let usedKg=0,usedEggs=0;return lines.map((l,i)=>{const last=i===lines.length-1,kg=last?batchRound(o.kg-usedKg):batchRound(w?weights[i]*o.kg/w:o.kg/lines.length),eggs=last?o.stockEggs-usedEggs:Math.floor(e?counts[i]*o.stockEggs/e:o.stockEggs/lines.length);usedKg+=kg;usedEggs+=eggs;return {kg,eggs}})}
